sys_hub_input_scripts.script:
{"input":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data.subflow_inputs;"}}

{"request_metadata":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data.subflow_inputs.input.request_metadata;"}}

{"save_to_record":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var gr = new GlideRecord("ml_predictor_results");
gr.solution = "7a3642f753b8021015caddeeff7b12ad";
gr.insert();
return gr;"}}

{"model_name":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var model = "docintel";

if(fd_data._2__genai_preprocessor.xformed_request.hasOwnProperty("model")) {
 model = fd_data._2__genai_preprocessor.xformed_request["model"];
}

return model;"}}

{"preprocessor_output":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/

var output = {};
output.task_id = fd_data.flow_var.task_id;
output.predictor_result = fd_data.flow_var.predictor_result;
output.result_attachment_ids = fd_data._3__now_llm_media.response_attachment_ids;"}}

{"is_prediction_enabled":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return !gs.getProperty("glide.platform_ml.disable_workflow",false);"}}

