{"outputs":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/


var output = [{
 "name": "result", 
 "parameters": {
 "binary_data": true
 }
 }];

return JSON.stringify(output);"}}

{"predictor_result":{"scriptActive":true,"script":"var gr = new GlideRecord('ml_predictor_results');
gr.initialize();
gr.insert();
return gr;"}}

{"inputs":{"scriptActive":true,"script":"
var options = fd_data.subflow_inputs.input.options;
var config = fd_data.subflow_inputs.input.config;
var inputs = [
 {
 "name": "archive",
 "shape": [
 1
 ],
 "datatype": "BYTES",
 "parameters": {
 "binary_data_size": "{byteSize}"
 }
 },
 {
 "name": "config",
 "shape": [
 1
 ],
 "datatype": "BYTES",
 "data": [
 config
 ]
 },
 {
 "name": "options",
 "shape": [
 1
 ],
 "datatype": "BYTES",
 "data": [
 options
 ]
 }
]


return JSON.stringify(inputs);
"}}

{"variable":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data.flow_var.predictor_result.sys_id;"}}

{"started_at":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return new GlideDateTime();"}}

{"parsed_input":{"scriptActive":true,"script":"/**
 * If the input type is string, parse it.
 */

var input = typeof fd_data.subflow_inputs.input == "string" ? JSON.parse(fd_data.subflow_inputs.input) : fd_data.subflow_inputs.input;
if (input["top_n"] == undefined) {
	input["internal_param_predict_top_n"] = "1";
} else {
	input["internal_param_predict_top_n"] = input["top_n"];
}
return input;"}}

{"error_attachment_id":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var content = {
 "error" : fd_data._2__now_llm_media.error_message,
 "task_id" : fd_data.flow_var.task_id,
 "usecase" : fd_data.flow_var.usecase
};

var inputStream = GlideStringInputStream.get(JSON.stringify(content));
return new GlideSysAttachment().write(fd_data.flow_var.predictor_result.sys_id, "ml_predictor_results", "error.json", "text/plain", inputStream);
"}}

{"error_attachment_sys_id":{"scriptActive":true,"script":"var content = {
 "task_id" : fd_data.flow_var.task_id,
 "error" : fd_data._3__now_llm_media.error_message,
 "usecase" : fd_data.flow_var.usecase
};
var inputStream = GlideStringInputStream.get(JSON.stringify(content));
var attachment_sys_id = new GlideSysAttachment().write(fd_data.flow_var.predictor_result.sys_id, "ml_predictor_results", "error.json", "text/plain", inputStream);
fd_data.flow_var.predictor_result.insert();
return attachment_sys_id;"}}

{"output":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var op = {};
op.attachment_sys_ids = fd_data.flow_var.attachment_sys_ids;
op.task_id = fd_data.flow_var.task_id;
op.predictor_result_id = fd_data.flow_var.predictor_result.getUniqueValue();

return op;"}}

